class MyEnumMeta(EnumMeta):
    def __contains__(cls, item):
        try:
            cls(item)
        except ValueError:
            return False
        else:
            return True


class AutoName(Enum, metaclass=MyEnumMeta):
    @staticmethod
    def _generate_next_value_(name: str, start: int, count: int, last_values: list[Any]) -> Any:
        return name


class Timeouts(IntEnum):
    COMMISSIONING_TIMEOUT = 60 * 10
    RMOD_DETECTION_TIMEOUT = 60 * 15
    EGATE_TIMEOUT = 60 * 10


class SimConfigType(str, AutoName):
    AIRPHONE_XML = auto()
    IPHY_XML = auto()
    CUS_YAML = auto()
    CUS_INI = auto()


class DevicesNames(str, AutoName):
    SIMULATOR = auto()
    AIRPHONE = auto()
    IPHY = auto()
    CUS = auto()
    ENB = auto()
    GNB = auto()
    CLOUD_BTS = auto()
    RTG = auto()


class CFG_WTS(str, AutoName):
    CONFIG_FP = auto()
